package mx.com.mesaregia.seguridad;
import mx.com.mesaregia.seguridad.application.service.impl.UsuarioServiceImpl; import mx.com.mesaregia.seguridad.application.service.AuditoriaService; import mx.com.mesaregia.seguridad.mapper.UsuarioMapper; import mx.com.mesaregia.seguridad.repository.*; import mx.com.mesaregia.seguridad.domain.entity.*; import mx.com.mesaregia.seguridad.api.request.AsignarRolRequest; import mx.com.mesaregia.seguridad.exception.BusinessRuleException; import org.junit.jupiter.api.*; import org.mockito.*; import static org.mockito.Mockito.*; import static org.junit.jupiter.api.Assertions.*; import java.util.Optional;
class UsuarioServiceImplTest { @Mock UsuarioRepository usuarios; @Mock RolRepository roles; @Mock AuditoriaService auditoria; UsuarioServiceImpl service; @BeforeEach void init(){MockitoAnnotations.openMocks(this);service=new UsuarioServiceImpl(usuarios,roles,new UsuarioMapper(),auditoria);} @Test void noPermiteRetirarUltimoAdmin(){Rol admin=new Rol();admin.setId(1L);admin.setCodigo("ADMIN");admin.setActivo(true);Rol ventas=new Rol();ventas.setId(2L);ventas.setCodigo("USER");ventas.setActivo(true);Usuario u=new Usuario();u.setId(10L);u.setNombre("Admin");u.setIdentificador("admin");u.setActivo(true);u.setRol(admin);u.setVersion(1L);when(usuarios.findById(10L)).thenReturn(Optional.of(u));when(roles.findById(2L)).thenReturn(Optional.of(ventas));when(usuarios.countByRolCodigoAndActivoTrue("ADMIN")).thenReturn(1L);assertThrows(BusinessRuleException.class,()->service.asignarRol(10L,new AsignarRolRequest(2L,1L,"Cambio")));}}
